<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<my-tab :datas="tabs" bgColor="#fff" height="80rpx" :current="type" @itemClick='itemClick' />
		<scroll-view scroll-y="true" class="scroll" @scrolltolower="loadMore">
			<block v-if="lists.length>0">
			<view class="order-items">
				<view style="height: 20rpx;"></view>
				<view class="order-item" v-for="(item,index) in lists" :key="index" @click="toNext(`/pages/order/order-detail?order_id=${item.order_id}`)">
					<view class="order-item-top">
						<view class="order-item-top-left">
							<text class="order-sn-text">{{item.add_time}}</text>
						</view>
						<view class="order-item-top-right">{{item.status_text}}</view>
					</view>
					<view class="goods">
						<view class="goods-item" v-for="(child,childIndex) in item.order_goods" :key="childIndex">
							<image :src="child.goods_img" class="goods-img" mode="aspectFit"/>
							<view class="goods-item-right">
								<view class="goods-name">{{child.goods_name}}</view>
								<view class="goods-spec">已选:{{child.item_name?child.item_name:'无'}}</view>
								<view class="goods-item-bot">
									<view class="goods-price">
										<text>¥</text>
										<text class="jiage">{{child.goods_price}}</text>
									</view>
									<view class="goods-num">x{{child.goods_num}}</view>
								</view>
							</view>
						</view>
					</view>
					<view class="order-item-info">
						<view class="info-right">
							<text class="small-text">实付：</text>
							<text class="fh-text">¥</text>
							<text class="price-text">{{item.order_amount}}</text>
						</view>
					</view>
					<view class="order-item-bot">
						<block v-if="item.order_status==-1">
							<button class="order-item-btn cancel" @click.stop="cancel_order(item)">取消订单</button>
							<button class="order-item-btn theme" @click.stop="getPay(item)">去支付</button>
						</block>
						<block v-else-if="item.order_status==1">
							<button class="order-item-btn cancel" @click.stop="toNext(`/pages/order/order-detail?order_id=${item.order_id}`)">查看订单</button>
						</block>
						<block v-else-if="item.order_status==2">
							<button class="order-item-btn cancel" @click.stop="toNext(`/pages/order/order-detail?order_id=${item.order_id}`)">查看订单</button>
							<button class="order-item-btn theme" v-if="item.order_status==2" @click.stop="confirm_order(item)">确认收货</button>
						</block>
						<block v-else-if="item.order_status==3">
							<button class="order-item-btn cancel" @click.stop="toNext(`/pages/order/order-detail?order_id=${item.order_id}`)">查看订单</button>
							<button class="order-item-btn theme" @click.stop="buy_again(item.order_id)">再次购买</button>
						</block>
						<block v-else>
							<button class="order-item-btn cancel" @click.stop="toNext(`/pages/order/order-detail?order_id=${item.order_id}`)">查看订单</button>
						</block>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			</block>
			<view class="empty-container" v-else>
				<u-empty text="暂无相关订单" :icon="emptyIcon" />
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				tabs: [{
					name: '全部',
				}, {
					name: '待支付',
				}, {
					name: '待配送',
				}, {
					name: '待收货',
				}, {
					name: '已完成',
				}],
				page: 1,
				pageNum: 10,
				type:0
			};
		},
		methods: {
			itemClick(type) {
				_this.type = type
				_this.page = 1
				_this.lists = []
				_this.get_dingdan()
			},
			loadMore(){
				if(_this.hasMore){
					_this.page++
					_this.get_dingdan()
				}
			},
			async get_dingdan(){
				const params = {
					pageIndex: _this.page,
					pageSize: _this.pageNum,
					status: _this.type,
				}
				const data = await _this.$post('port/dingdan_list', params)
				if(data.code==200){
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length >= _this.pageNum
				}else{
					_this.hasMore = false
				}
				if (_this.load) {
					_this.load = false
				}
			},
			//取消订单
			async cancel_order(item){
				uni.showModal({
					title:'提示',
					content:'确定取消?',
					success(res) {
						if(res.confirm){
							_this.qx_dd(item)
						}
					}
				})
			},
			async qx_dd(item){
				const params = {
					id: item.order_id,
				}
				const data = await _this.$post('port/dingdan_cancel', params)
				if(data.code==200){
					item.order_status = 4
					item.status_text = '已取消'
					this.$u.toast(data.msg)
				}else{
					this.$u.toast(data.msg)
				}
			},
			//确认订单
			async confirm_order(item){
				uni.showModal({
					title:'提示',
					content:'确定已收到商品?',
					success(res) {
						if(res.confirm){
							_this.qr_dd(item)
						}
					}
				})
			},
			async qr_dd(item){
				const params = {
					id: item.order_id,
				}
				const data = await _this.$post('port/dingdan_confirm', params)
				if(data.code==200){
					item.order_status = 3
					item.status_text = '已完成'
					this.$u.toast(data.msg)
				}else{
					this.$u.toast(data.msg)
				}
			},
			//再次购买
			buy_again(order_id){
				//跳转到确认订单页面
				this.$u.route({
					url: 'pages/cart/cart-submit',
					params: {
						action: 'buy_again',
						order_id
					}
				})
			},
			async getPay(item){
				if (item.is_xcx==1) {
					// #ifndef MP-WEIXIN
					this.$u.toast('请在小程序端完成支付')
					return
					// #endif
				} else if(this.is_wx){
					if (item.pay_code=='alipayMobile' || item.pay_code == 'weixinH5') {
						this.$u.toast('请在浏览器端完成支付')
						return;
					}
				}else{
					if (item.pay_code=='weixin') {
						this.$u.toast('请在微信浏览器端完成支付')
						return;
					}
				}
				const params = {
					id: item.order_id,
					type:1
				}
				// #ifdef MP-WEIXIN
				let openid = uni.getStorageSync('unionid')?uni.getStorageSync('unionid'):uni.getStorageSync('openid')
				params.is_xcx = 1
				params.openid = openid
				// #endif
				const data = await _this.$post('port/pay_order', params)
				if(data.code==200){
					if (item.is_xcx==1) {
						uni.requestPayment({
							provider: 'wxpay',
							timeStamp: data.result.timeStamp+'',
							nonceStr: data.result.nonceStr,
							package: data.result.package,
							signType: data.result.signType,
							paySign: data.result.sign,
							success(res) {
								console.log('success:' + JSON.stringify(res));
								item.order_status = 1
								item.status_text = '待发货'
								_this.$u.toast('支付成功')
							},
							fail(err) {
								_this.$u.toast('支付失败')
								console.log('fail:' + JSON.stringify(err));
							}
						});
					}else{
						if(data.result.pay_code == 'alipayMobile'){
							// location.href = data.result.url
							location.replace(data.result.url)
							// _this.finish()
						}else if (data.result.pay_code == 'weixinH5') {
							location.href = data.result.url
							uni.showModal({
								title:'提示',
								content:'请确认是否已完成支付',
								confirmText:'已完成支付',
								cancelText:'未完成支付',
								success(res) {
									_this.queryOrder(data.result.order_sn,item)
								}
							})
						}else{
							let wx_result = data.result.wx_result
							function onBridgeReady(){
							   WeixinJSBridge.invoke(
							      'getBrandWCPayRequest', wx_result,
							      function(res){
									  if(res.err_msg == "get_brand_wcpay_request:ok" ){
											// 使用以上方式判断前端返回,微信团队郑重提示：
											//res.err_msg将在用户支付成功后返回ok，但并不保证它绝对可靠。
											uni.$u.toast('支付成功')
											item.order_status = 1
											item.status_text = '待发货'
									  }else if (res.err_msg=="get_brand_wcpay_request:cancel") {
											uni.$u.toast('您已取消支付')
									  }else{
										  uni.$u.toast('支付失败')
									  }
							   }); 
							}
							if (typeof WeixinJSBridge == "undefined"){
							   if( document.addEventListener ){
							       document.addEventListener('WeixinJSBridgeReady', onBridgeReady, false);
							   }else if (document.attachEvent){
							       document.attachEvent('WeixinJSBridgeReady', onBridgeReady); 
							       document.attachEvent('onWeixinJSBridgeReady', onBridgeReady);
							   }
							}else{
							   onBridgeReady();
							}
						}
					}
				}else{
					this.$u.toast(data.msg)
				}
			},
			//查询订单支付状态
			async queryOrder(order_sn,item){
				let params = {
					order_sn
				}
				const data = await _this.$post('port/chaxun_order', params)
				if (data.code==200) {
					item.order_status = 1
					item.status_text = '待发货'
				} else if(data.code==100){
					uni.$u.toast('未完成支付,请重试!')
				}else{
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}
			}
		},
		onLoad(e) {
			_this = this;
			if(e.type){
				_this.type = e.type
			}
			uni.$on('doOrder',res=>{
				if(res.type==1){
					_this.lists[res.index]['order_status']=-2
					_this.lists[res.index]['status_text']='已取消'
				}else if(res.type==2){
					_this.lists[res.index]['order_status']=3
					_this.lists[res.index]['status_text']='已完成'
				}else if(res.type==3){
					_this.lists[res.index]['order_status']=1
					_this.lists[res.index]['status_text']='待发货'
				}else{
					//评论
					_this.lists[res.index]['order_status']=4
					_this.lists[res.index]['status_text']='已完成'
				}
			})
			_this.get_dingdan()
		},
		onUnload() {
			uni.$off('doOrder')
		},
		components: {}
	}
</script>

<style lang="scss" scoped>
	@import "static/css/order.scss";
	.container {
		height: 100%;
		.scroll{
			height: calc(100% - 80rpx);
			.order-items{
				padding: 0 30rpx;
			}
		}
	}
</style>